<div class="module-grid"><?php $i=0; foreach ($modules as $key=>$module): $i++; ?><a class="module-card" href="<?= e(url('/module').'&key='.$key) ?>"><div class="card-top"><span class="module-icon"><?= e($module['icon']) ?></span><span class="muted">0<?= $i ?></span></div><h3><?= e($module['name']) ?></h3><p><?= e($module['description']) ?></p><span class="card-arrow" aria-hidden="true">↗</span></a><?php endforeach; ?></div>
